// @rpg/protocol: TypeScript types and codecs for the game protocol (proto/game/v1).
// The schemas in ./gen are generated by `make gen`; do not edit them by hand.
import { fromBinary, toBinary } from "@bufbuild/protobuf";
import { ClientMessageSchema } from "./gen/game/v1/client_pb.ts";
import type { ClientMessage } from "./gen/game/v1/client_pb.ts";
import { ServerBatchSchema } from "./gen/game/v1/server_pb.ts";
import type { ServerBatch } from "./gen/game/v1/server_pb.ts";

export * from "./gen/game/v1/common_pb.ts";
export * from "./gen/game/v1/client_pb.ts";
export * from "./gen/game/v1/server_pb.ts";
export { create } from "@bufbuild/protobuf";
export type { MessageInitShape } from "@bufbuild/protobuf";

/** Encodes a ClientMessage into one WebSocket binary frame. */
export function encodeClientMessage(message: ClientMessage): Uint8Array {
  return toBinary(ClientMessageSchema, message);
}

/** Decodes one server WebSocket binary frame. Throws on malformed input. */
export function decodeServerBatch(frame: Uint8Array): ServerBatch {
  return fromBinary(ServerBatchSchema, frame);
}
